with filtered as (select id, customer_id, plan, end_date, monthly_fee, status, floor(monthly_fee) as monthly_fee_whole from subscriptions where status = 'PAUSED' and end_date >= to_date('2023-09-12')), joined as (select a.*, d.city, d.email, d.signup_date from filtered a inner join customers d on a.customer_id = d.id), attributed as (select a.*, sub.id as subscription_id, sub.plan as subscription_plan, sub.monthly_fee as subscription_monthly_fee from joined a left join subscriptions sub on a.customer_id = sub.customer_id and a.end_date >= sub.start_date and a.end_date < sub.end_date + interval '14' day), ranked as (select *, rank() over (partition by plan order by signup_date) as row_num from attributed qualify row_num = 1) select id, plan, monthly_fee, email, subscription_id, subscription_plan, subscription_monthly_fee, row_num, case when plan rlike '^(enterprise|premium)$' then 'GROUP_B' when plan rlike '^(basic|standard)$' then 'PRIORITY' else 'EXTENDED' end as plan_zone from ranked;
